// Twin of "SyncView — Urgent Tweak → Slack", aimed the other way: that one
// pings the EDITOR in #video-editing about a video at Tweaks Needed; this one
// DMs KASPER about a card parked at Kasper Approval.
//
// The recipient is NOT taken from the request. The browser sends card context
// only, exactly as the editor ping does, so nothing a page can post decides who
// gets messaged.
const item = $input.first().json;
const b = (item && item.body) ? item.body : item;
const clean = (v, max) => String(v == null ? '' : v)
  .replace(/[<>@]/g, '')
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/\s{2,}/g, ' ')
  .trim()
  .slice(0, max || 80);

const client = clean(b && b.client, 80);
const name = clean(b && (b.name || b.postName), 120);
const surface = String((b && b.surface) || '').trim() === 'samples' ? 'samples' : 'calendar';
const component = ['video', 'graphic', 'caption', 'title'].includes(String((b && b.component) || '').trim())
  ? String(b.component).trim()
  : '';

// The link is rebuilt here rather than trusted: a URL from the request is only
// accepted when it is on the SyncView origin, so a forged payload cannot turn a
// Slack DM from the SyncView Bot into a link to somewhere else.
const ORIGIN = 'https://syncview.synchrosocial.com/';
const fallback = ORIGIN + '#kasper' + (surface === 'samples' ? '/samples' : '');
const asked = String((b && b.url) || '').trim();
const url = (asked.indexOf(ORIGIN) === 0 && asked.length <= 300) ? asked : fallback;

// A ping with no card behind it is refused: the DM would say nothing useful and
// the SMM would never learn it went nowhere.
const valid = !!(client || name);
const error = valid ? '' : 'Missing client and card name';

const COMPONENT_LABELS = { video: 'Video', graphic: 'Thumbnail', caption: 'Caption', title: 'Title' };
const waitingOn = component ? (COMPONENT_LABELS[component] || component) : '';

let text = 'URGENT — WAITING ON YOUR REVIEW';
if (client) text += '\nClient: ' + client;
if (name) text += '\nCard: ' + name;
if (waitingOn) text += '\nWaiting on: ' + waitingOn;
text += '\nYour review tab: ' + url;
text += '\n\nIt is in the Urgent section at the top.';

return [{ json: { valid, error, client, name, surface, component, url, text } }];
